mapper.select:
SELECT sc.id,sc.score_category as scoreCategory,dc.name as scoreCategoryName, CASE WHEN sc.semester='1' THEN '第一学期' WHEN sc.semester='2' THEN '第二学期' ELSE '' END as semester, cg.title as grade,cc.title as classs,'1' as type, concat(cg.title, ' ', cc.title) as gradeClassName, sc.score_time,sc.score_time as scoreCreateTime from `score_category` sc
left join `score_score_category` ssc on sc.id=ssc.score_category_id left join `score` s on s.id=ssc.score_id left join `score_user` su on s.id=su.score_id left join `user` u on u.id=su.user_id left join course cc on cc.id=su.classs left join course cg on cg.id=su.grade left join sys_dictionary dc on dc.id=sc.score_category
and sc.score_category=#{score.scoreCategory}
and sc.score_time=#{score.scoreTime}
and sc.semester=#{score.semester}
and su.grade=#{score.grade}
and su.classs=#{score.classs}
and su.classs in
#{item}
GROUP BY sc.id,dc.name,sc.semester, cg.title,cc.title order by sc.create_time desc

SELECT s.id,su.user_id as userId,su.`real_name` as username,su.user_no as userNo,dc.name as scoreCategory, CASE WHEN sc.semester='1' THEN '第一学期' WHEN sc.semester='2' THEN '第二学期' ELSE '' END as semester, sc.score_time,CASE WHEN u.gender='1' THEN '男' ELSE '女' END as genderName, cg.id as grade,cc.id as classs,'2' as type,cc.science_humanities_class as scienceHumanitiesClass, concat(cg.title, ' ', cc.title) as gradeClassName, cg.title as gradeName,cc.title as className, s.chinese,s.mathematics,s.english, s.physics,s.chemistry,s.organism,s.science as science, s.history,s.politics,s.geography,s.humanities as humanities,
s.total_score,s.create_time as createTime,s.create_time as scoreCreateTime from `score` s left join `score_user` su on s.id=su.score_id left join `user` u on u.id=su.user_id
left join `score_score_category` ssc on s.id=ssc.score_id left join `score_category` sc on sc.id=ssc.score_category_id left join course cc on cc.id=su.classs left join course cg on cg.id=su.grade left join sys_dictionary dc on dc.id=sc.score_category
and u.name like concat('%',#{score.username},'%')
and su.user_id=#{score.userId}
and sc.semester=#{score.semester}
and su.grade=#{score.grade}
and sc.id=#{score.scoreCategoryId}
and sc.score_category=#{score.scoreCategory}
and su.classs=#{score.classs}
and su.classs in
#{item}
order by sc.create_time desc,s.total_score desc,su.user_no asc

  select u.grade as gradeId,cg.title as grade,



          ROUND((count(c${item.code}.${item.code})/count(s.id))*100,0) ${item.code}Count,



  count(DISTINCT u.classs) as classCount

  from user u
  left join score_user su on u.id=su.user_id
  left join (select s.* from score s
  left join `score_score_category` ssc on s.id=ssc.score_id
  left join `score_category` sc on sc.id=ssc.score_category_id


          and sc.semester=#{score.semester}


          and sc.score_category=#{score.scoreCategory}



          and sc.score_time=#{score.scoreTime}



  )s on s.id=su.score_id
  left join `score_score_category` ssc on s.id=ssc.score_id
  left join `score_category` sc on sc.id=ssc.score_category_id

  left join course cg on cg.id=u.grade




          left join (select s.* from score s
          left join `score_score_category` ssc on s.id=ssc.score_id
          left join (select * from `score_category`


                    and semester=#{score.semester}


                    and score_category=#{score.scoreCategory}



                    and score_time=#{score.scoreTime}


          )sc on sc.id=ssc.score_category_id
          LEFT JOIN score_user suu ON ssc.score_id = suu.score_id
          left join (select parent_id,total_score from course where code=#{item.code} and type='scoreCourse' and status='1')cs on cs.parent_id=suu.grade
          where s.${item.code}>=cs.total_score*0.6

          ) c${item.code} on c${item.code}.id=s.id






            and u.grade=#{score.grade}



            and u.classs in

                #{item}









GROUP BY u.grade order by cg.sort_by asc

select u.grade AS gradeId, cg.title AS grade,u.classs as classsId,cc.title as classs,sc.id as categoryId,dsc.`name` as categoryName, CASE WHEN sc.semester='1' THEN '第一学期' when sc.semester='2' THEN '第二学期' ELSE '' END as semester, sc.semester as semesterId,
ROUND((count(c${item.code}.${item.code})/count(s.id))*100,0) ${item.code}Count,
count(DISTINCT u.id) as userCount
from `score_category` sc left join `score_score_category` ssc on sc.id=ssc.score_category_id
left join (select s.id from score s
left join `score_score_category` ssc on s.id=ssc.score_id )s on s.id=ssc.score_id
left join score_user su on s.id=su.score_id left join user u on u.id=su.user_id
left join course cg on cg.id=u.grade left join course cc on cc.id=u.classs LEFT JOIN sys_dictionary dsc ON dsc.id = sc.score_category
left join (select s.id, s.${item.code} from score s LEFT JOIN score_user suu ON s.id = suu.score_id left join (select parent_id,total_score from course where code=#{item.code} and type='scoreCourse' and status='1')cs on cs.parent_id=suu.grade where s.${item.code}>=cs.total_score*0.6
) c${item.code} on c${item.code}.id=s.id
and u.grade=#{score.grade}
and u.classs=#{score.classs}
and sc.score_category=#{score.scoreCategory}
and u.classs in
#{item}
GROUP BY u.grade,u.classs,sc.id,sc.semester ORDER BY cg.sort_by asc,cc.sort_by asc,sc.score_time desc

SELECT u.id as userId,su.`real_name` as username,su.user_no,u.age,u.phone, CASE WHEN sc.semester='1' THEN '第一学期' when sc.semester='2' THEN '第二学期' ELSE '' END as semester, CASE WHEN u.gender='1' THEN '男' ELSE '女' END as genderName, cg.title as grade,cc.title as classs, concat(cg.title, ' ', cc.title) as gradeClassName, s.chinese,s.mathematics,s.english, s.physics,s.chemistry,s.organism,s.science as science, s.history,s.politics,s.geography,s.humanities as humanities, s.total_score,s.create_time as createTime,u.create_time as userCreateTime from score s left join `score_user` su on s.id=su.score_id left join `user` u on u.id=su.user_id left join `score_score_category` ssc on s.id=ssc.score_id left join `score_category` sc on sc.id=ssc.score_category_id left join course cg on cg.id=u.grade left join course cc on cc.id=u.classs
and sc.id=#{score.scoreCategoryId}
and sc.score_category=#{score.scoreCategory}
and su.grade=#{score.grade}
and su.classs=#{score.classs}
and su.classs in
#{item}
and s.${score.type}>= (select total_score from course where parent_id=#{score.grade} and code=#{score.type} and type='scoreCourse' and status='1')*0.6
and s.${score.type}<(select total_score from course where parent_id=#{score.grade} and code=#{score.type} and type='scoreCourse' and status='1')*0.6
order by cg.sort_by asc,cc.sort_by asc,s.total_score desc,su.user_no asc
